<script setup lang="ts">
import { BarChart } from 'echarts/charts'; import { GridComponent, TooltipComponent } from 'echarts/components'; import { init, type ECharts, use } from 'echarts/core'; import { CanvasRenderer } from 'echarts/renderers'; import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'; import request from '@/utils/request'; import type { ApiResponse } from '@/types'
use([BarChart, GridComponent, TooltipComponent, CanvasRenderer])
const stats=ref<any>({}); const users=ref<any[]>([]); const chartEl=ref<HTMLElement>(); let chart:ECharts|undefined
onMounted(async()=>{const [a,b]=await Promise.all([request.get<ApiResponse<any>>('/statistics/admin/overview'),request.get<ApiResponse<any[]>>('/users')]);stats.value=a.data.data;users.value=b.data.data;await nextTick();if(chartEl.value){chart=init(chartEl.value);chart.setOption({grid:{left:36,right:20,top:20,bottom:30},tooltip:{trigger:'axis'},xAxis:{type:'category',data:['用户','课程','已发布','考试']},yAxis:{type:'value'},series:[{type:'bar',barWidth:34,data:[stats.value.user_total,stats.value.course_total,stats.value.published_courses,stats.value.exam_total],itemStyle:{color:'#2f87ff',borderRadius:[8,8,0,0]}}]})}});onBeforeUnmount(()=>chart?.dispose())
</script>
<template><section class="page"><header class="page-header"><div><p class="eyebrow">PLATFORM CONTROL</p><h1>管理中心</h1><p>平台运行状态与核心资源，一览无余。</p></div><el-tag type="success" size="large">系统运行正常</el-tag></header><div class="metric-grid"><article><span>用户总数</span><strong>{{ stats.user_total||0 }}</strong><small>{{ stats.active_users||0 }} 位正常用户</small></article><article><span>课程总数</span><strong>{{ stats.course_total||0 }}</strong><small>{{ stats.published_courses||0 }} 门已发布</small></article><article><span>考试总数</span><strong>{{ stats.exam_total||0 }}</strong><small>平台测评</small></article><article><span>学习时长</span><strong>{{ Math.round((stats.learning_seconds||0)/3600) }}h</strong><small>累计有效时长</small></article></div><div class="panel" style="margin-bottom:28px"><div class="panel-title"><h2>平台资源概览</h2><span>实时数据</span></div><div ref="chartEl" style="height:280px"></div></div><div class="panel table-panel"><div class="panel-title"><h2>用户管理</h2><span>共 {{ users.length }} 人</span></div><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="email" label="邮箱"/><el-table-column label="角色"><template #default="scope"><el-tag v-for="r in scope.row.roles" :key="r.id" effect="plain">{{ r.name }}</el-tag></template></el-table-column><el-table-column prop="status" label="状态"/></el-table></div></section></template>
